 #define UNAVAILABLE_COUNTER		BIT_ULL(63)
 #define CMRC_FLAG_UNAVAILABLE_BIT	BIT(0)
+#define MMRC_FLAG_UNAVAILABLE_BIT	BIT(0)
+#define FIXPOINT_LOW_BITS		16
 
